import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';
class UnitsScreen extends ConsumerStatefulWidget{const UnitsScreen({super.key});@override ConsumerState<UnitsScreen> createState()=>_UnitsScreenState();}
class _UnitsScreenState extends ConsumerState<UnitsScreen>{late String weight,distance,temperature;@override void initState(){super.initState();final c=ref.read(appControllerProvider);weight=c.weightUnit;distance=c.distanceUnit;temperature=c.temperatureUnit;}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Units and measurements')),body:ListView(padding:const EdgeInsets.all(18),children:[DropdownButtonFormField<String>(value:weight,decoration:const InputDecoration(labelText:'Weight'),items:const[DropdownMenuItem(value:'lb',child:Text('Pounds (lb)')),DropdownMenuItem(value:'kg',child:Text('Kilograms (kg)'))],onChanged:(v)=>setState(()=>weight=v!)),const SizedBox(height:16),DropdownButtonFormField<String>(value:distance,decoration:const InputDecoration(labelText:'Distance'),items:const[DropdownMenuItem(value:'mi',child:Text('Miles (mi)')),DropdownMenuItem(value:'km',child:Text('Kilometers (km)'))],onChanged:(v)=>setState(()=>distance=v!)),const SizedBox(height:16),DropdownButtonFormField<String>(value:temperature,decoration:const InputDecoration(labelText:'Temperature'),items:const[DropdownMenuItem(value:'°F',child:Text('Fahrenheit (°F)')),DropdownMenuItem(value:'°C',child:Text('Celsius (°C)'))],onChanged:(v)=>setState(()=>temperature=v!)),const SizedBox(height:20),const Text('Existing records keep the unit that was saved with each entry. These preferences affect new entries and default displays.'),const SizedBox(height:20),FilledButton(onPressed:()async{await ref.read(appControllerProvider).saveUnits(weight:weight,distance:distance,temperature:temperature);if(mounted)Navigator.pop(context);},child:const Text('Save preferences'))]));}
